G=load()
def dihedral(p):
    out=[]; cur=p.tolist()
    for _ in range(4):
        out.append(np.array(cur)); out.append(np.array([row[::-1] for row in cur]))
        cur=[list(x) for x in zip(*cur[::-1])]
    return out

def analyze(I,O):
    I=np.array(I); O=np.array(O)
    h,w=I.shape
    sep_rows=[r for r in range(h) if len(set(map(int,I[r])))==1]
    sep_cols=[c for c in range(w) if len(set(map(int,I[:,c])))==1]
    sr,sc=sep_rows[0],sep_cols[0]
    from collections import Counter
    sep=I[sr][sc]
    cnt=Counter(map(int,I.flatten()))
    sepcol={sep}
    bgc=cnt.most_common(1)[0][0]
    while True:
        rest=[c for c in cnt if c not in sepcol]
        if len(rest)==2: break
    shc=min(rest,key=lambda c: cnt[c])
    quad=I[sr+1:h, sc+1:w]
    pts=np.argwhere(quad==shc)
    r0,r1,c0,c1=pts.min(0),pts.max(0),pts.min(1),pts.max(1)
    shape=quad[r0:r1+1, c0:c1+1]==shc
    oh,ow=O.shape
    m=(O==shc).astype(int)
    return dict(sr=sr,sc=sc,shc=shc,bg=bgc,sep=sep,m=m,shape=shape,oh=oh,ow=ow)

