            for dc in range(-rw,tw+rw+1):
                T=np.zeros_like(m,dtype=int)
                for ai in range(th):
                    for bi in range(tw):
                        if tv[ai][bi]:
                            rr,cc=2*ai+dr, 2*bi+dc
