G=load()
def solve(I):
    A=np.array(I); H,W=A.shape
    sr=next(r for r in range(H) if len(set(map(int,A[r])))==1)
    sc=next(c for c in range(W) if len(set(map(int,A[:,c])))==1)
    sep=int(A[sr][sc]); bgv=Counter(map(int,A.flatten())).most_common(1)[0][0]
    quads={'TL':A[:sr,:sc],'TR':A[:sr,sc+1:],'BL':A[sr+1:,0:sc],'BR':A[sr+1:,sc+1:]}
    src=next(nm for nm,Q in quads.items() if (Q!=bgv).any())
    Q=quads[src]
    nz=np.argwhere(Q!=bgv); r0,c0=nz[:,0].min(),nz[:,1].min(); r1,c1=nz[:,0].max(),nz[:,1].max()
    sub=Q[r0:r1+1,c0:c1+1]; mm=sub!=bgv; sh_,sw_=mm.shape
    # scale 2x each cell; place scaled crop into each of the four quadrant-aligned positions around center
    out=np.full((2*sh_,2*sw_),sep,int)
    pieces=[]
    for fct in Df:
        p=fct(np.kron(mm.astype(int),np.ones((2,2),int))); pieces.append(p)
    # try OR placements: each piece positioned so its bbox corner coincides with a quadrant edge (center)
    regmap={'TL':(0,0),'TR':(0,sw_),'BL':(sh_,0),'BR':(sh_,sw_)}
    pred=np.zeros_like(out,dtype=bool)
    for nm,(dr,dc) in regmap.items():
        for pi,p in enumerate(pieces):
            pred[dr:dr+p.shape[0],dc:dc+p.shape[1]] |= p
    res=np.where(pred,sep,bgv)
    return [[int(x) for x in r] for r in res]
for n_ in range(1,9):
    p=solve(G[f'Demo pair {n_} input']); o=G[f'Demo pair {n_} output']
    print(n_,p==o, sum(a!=b for a,b in zip(p,o)))

